#include <cmath>
using namespace std;

int main() {
    long long L, R;
    int N;
    cin >> L >> R >> N;
    bool found = false;
    for (long long num = L; num <= R; num++) {
        long long sum = 0, tmp = num;
        while (tmp > 0) {
            int d = tmp % 10;
            long long pw = 1;
            for (int i = 0; i < N; i++) pw *= d;
            sum += pw;
            tmp /= 10;
        }
        if (sum == num) {
            cout << num << endl;
            found = true;
        }
    }
    if (!found) cout << "None" << endl;
    return 0;
}

